    UpperSemicontinuousAt (fun t : ℂ => u (z + t • v)) 0

theorem LineSubharmonicOn.comp_submodule_add {u : E → ℝ} {D : Set E}
    (hl : LineSubharmonicOn u D) (K : Submodule ℂ E) (a : E) :
    LineSubharmonicOn (fun w : K => u (w + a)) {w : K | (w : E) + a ∈ D}

theorem LineSubharmonicOn.discPshOn_of_nonneg [FiniteDimensional ℂ E] {u : E → ℝ} {D : Set E}
    (hD : IsOpen D) (hpos : ∀ x ∈ D, 0 ≤ u x) (hl : LineSubharmonicOn u D) :
    DiscPshOn (fun x => (u x : EReal)) D

theorem exists_upper_bound_of_isCompact {X : Type*} [PseudoMetricSpace X] {u : X → ℝ}
    {D K : Set X}
    (hbdd : ∀ p ∈ D, ∃ r > 0, BddAbove (u '' ball p r)) (hK : IsCompact K) (hKD : K ⊆ D) :
    ∃ C : ℝ, ∀ x ∈ K, u x ≤ C

theorem plurisubharmonicOn_comp_holomorphic
    {F : ComplexModel k → ComplexModel n} {u : ComplexModel n → EReal}
    {U : Set (ComplexModel k)} {V : Set (ComplexModel n)}
    (hU : IsOpen U) (hF : DifferentiableOn ℂ F U) (hFV : MapsTo F U V)
    (hu : PlurisubharmonicOn u V) :
    PlurisubharmonicOn (fun y => u (F y)) U

theorem adaptedRadialKernel_tsupport_subset_norm (R : ℝ) (hR : 0 < R) (j : ℕ) :
    tsupport (adaptedRadialKernel μ R hR j) ⊆
      {x | ‖adaptedComplexModelEquiv x‖ ≤ R / ((j : ℝ) + 1)}

theorem IsPshRepresentative.restrict (μ : Measure E) {T : 𝓓'(Ω, ℝ)}
    {u : E → EReal} (hu : IsPshRepresentative μ T u) (hUΩ : U ≤ Ω) :
    IsPshRepresentative μ (restrictDistribution T hUΩ) u

theorem AdaptedRadialKernelData.cutoff_eq_one_of_coordinate_displacement
    {μ : Measure E} {Ω : Opens E} {x : E}
    (D : AdaptedRadialKernelData μ Ω x) {z y : E}
    (hz : z ∈ closure (D.inner : Set E))
    (hy : ‖adaptedComplexModelEquiv (y - z)‖ ≤ D.radius) :
    D.cutoff y = 1

theorem exists_adaptedRadialKernelData
    (μ : Measure E) [μ.IsAddHaarMeasure] {Ω : Opens E} {x : E}
    (hx : x ∈ Ω) : Nonempty (AdaptedRadialKernelData μ Ω x)

theorem exists_nonneg_testFunction_one_le_on_compact {K : Set E}
    (hK : IsCompact K) (hKΩ : K ⊆ Ω) :
    ∃ φ : 𝓓(Ω, ℝ), (∀ x, 0 ≤ φ x) ∧ ∀ x ∈ K, 1 ≤ φ x

theorem exists_pshRepresentative_of_decreasing_approximation
    (μ : Measure E) [μ.IsAddHaarMeasure] {Ω : Opens E}
    {T : 𝓓'(Ω, ℝ)} {f : ℕ → E → ℝ}
    (hf : IsDecreasingSmoothPshApproximation μ T f) :
    ∃ u : E → EReal, IsPshRepresentative μ T u

theorem isCompact_highValue_sphere {u : ℂ → ℝ} {U : Set ℂ}
    (hu : DiscPshOn (fun z => (u z : EReal)) U)
    {c : ℂ} {r A : ℝ} (hD : sphere c r ⊆ U) :
    IsCompact {z ∈ sphere c r | A ≤ u z}

theorem nonempty_isCompact_highValue_sphere {u : ℂ → ℝ} {U : Set ℂ}
    (hu : DiscPshOn (fun z => (u z : EReal)) U) (hU : IsOpen U)
    {c : ℂ} {r : ℝ} (hr : 0 < r) (hD : closedBall c r ⊆ U) :
    {z ∈ sphere c r | u c ≤ u z}.Nonempty ∧
      IsCompact {z ∈ sphere c r | u c ≤ u z}

theorem isClosed_hopf_relation
    {E : Type*} [NormedAddCommGroup E] [NormedSpace ℂ E] :
    IsClosed {p : sphere (0 : E) 1 × sphere (0 : E) 1 | hopf p.1 = hopf p.2}
